insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 2)', '1', 'إِنَّ وَلَعَلَّ (частицы إِنَّ и لَعَلَّ)', '<b>Суть правила.</b> إِنَّ усиливает утверждение, а لَعَلَّ выражает надежду или вероятность. Обе частицы ставят свое имя в винительный падеж, а сказуемое оставляют в именительном. Со слитными местоимениями получаются إِنِّي، إِنَّكَ، إِنَّهُ и لَعَلِّي، لَعَلَّكَ، لَعَلَّهُ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">إِنَّ الطَّالِبَ مُجْتَهِدٌ.</b> — Поистине, студент усердный.</li><li><b dir="rtl" lang="ar">لَعَلَّهُمْ فِي الْفَصْلِ.</b> — Возможно, они в классе.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 5–11.</span>', '1', 'rule', 'إِنَّ усиливает утверждение, а لَعَلَّ выражает надежду или вероятность. Обе частицы ставят свое имя в винительный падеж, а сказуемое оставляют в именительном. Со слитными местоимениями получаются إِنِّي، إِنَّكَ، إِنَّهُ и لَعَلِّي، لَعَلّ'),
('Мединский курс (Том 2)', '1', 'أَمْ وَهَمْزَةُ التَّعْيِينِ (أَمْ и вопрос с выбором)', '<b>Суть правила.</b> В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَمِنَ الْهِنْدِ أَنْتَ أَمْ مِنْ بَاكِسْتَانَ؟</b> — Ты из Индии или из Пакистана?</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 5–11.</span>', '2', 'rule', 'В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».'),
('Мединский курс (Том 2)', '1', 'ذُو وَذَاتُ (обладающий и обладающая)', '<b>Суть правила.</b> ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا رَجُلٌ ذُو خُلُقٍ.</b> — Это человек с хорошим нравом.</li><li><b dir="rtl" lang="ar">هَذِهِ طَالِبَةٌ ذَاتُ عِلْمٍ.</b> — Это студентка, обладающая знанием.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 5–11.</span>', '3', 'rule', 'ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.'),
('Мединский курс (Том 2)', '1', 'الِاسْمُ الْمَنْقُوصُ (недостаточное имя)', '<b>Суть правила.</b> Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا قَاضٍ.</b> — Это судья.</li><li><b dir="rtl" lang="ar">سَلَّمْتُ عَلَى قَاضٍ.</b> — Я поприветствовал судью.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 5–11.</span>', '4', 'rule', 'Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.'),
('Мединский курс (Том 2)', '1', 'مِائَةٌ وَأَلْفٌ (числа сто и тысяча)', '<b>Суть правила.</b> После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مِائَةُ كِتَابٍ.</b> — Сто книг.</li><li><b dir="rtl" lang="ar">أَلْفُ سَيَّارَةٍ.</b> — Тысяча автомобилей.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 5–11.</span>', '5', 'rule', 'После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.'),
('Мединский курс (Том 2)', '2', 'لَيْسَ وَضَمَائِرُهَا (لَيْسَ и ее формы)', '<b>Суть правила.</b> لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَسْتُ مُتْعَبًا.</b> — Я не устал.</li><li><b dir="rtl" lang="ar">لَسْنَ غَائِبَاتٍ.</b> — Они, женщины, не отсутствуют.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 12–17.</span>', '1', 'rule', 'لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.'),
('Мединский курс (Том 2)', '2', 'الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ (усилительная بِ в сказуемом لَيْسَ)', '<b>Суть правила.</b> К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَيْسَ الطَّالِبُ بِغَائِبٍ.</b> — Студент вовсе не отсутствует.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 12–17.</span>', '2', 'rule', 'К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.'),
('Мединский курс (Том 2)', '2', 'تَقْدِيمُ خَبَرِ إِنَّ (сказуемое إِنَّ перед ее именем)', '<b>Суть правила.</b> Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">إِنَّ فِي الْفَصْلِ طَالِبًا.</b> — Поистине, в классе есть студент.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 12–17.</span>', '3', 'rule', 'Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.'),
('Мединский курс (Том 2)', '3', 'اسْمُ التَّفْضِيلِ (сравнительная и превосходная степень)', '<b>Суть правила.</b> Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">خَالِدٌ أَطْوَلُ مِنْ حَامِدٍ.</b> — Халид выше Хамида.</li><li><b dir="rtl" lang="ar">هُوَ أَحْسَنُ الطُّلَّابِ.</b> — Он лучший из студентов.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 18–25.</span>', '1', 'rule', 'Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.'),
('Мединский курс (Том 2)', '3', 'لَكِنَّ وَكَأَنَّ (частицы «но» и «как будто»)', '<b>Суть правила.</b> لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الْبَيْتُ صَغِيرٌ لَكِنَّهُ جَمِيلٌ.</b> — Дом маленький, но красивый.</li><li><b dir="rtl" lang="ar">كَأَنَّ الْقَمَرَ مِصْبَاحٌ.</b> — Луна словно светильник.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 18–25.</span>', '2', 'rule', 'لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.'),
('Мединский курс (Том 2)', '3', 'الْأَعْدَادُ ١١–٩٠ (числа 11–90)', '<b>Суть правила.</b> В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةَ عَشَرَ طَالِبًا.</b> — Тринадцать студентов.</li><li><b dir="rtl" lang="ar">رَأَيْتُ عِشْرِينَ طَالِبًا.</b> — Я увидел двадцать студентов.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 18–25.</span>', '3', 'rule', 'В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.'),
('Мединский курс (Том 2)', '3', 'الْعَدَدُ التَّرْتِيبِيُّ (порядковые числительные)', '<b>Суть правила.</b> Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الدَّرْسُ الثَّالِثُ.</b> — Третий урок.</li><li><b dir="rtl" lang="ar">الصَّفْحَةُ الْخَامِسَةُ.</b> — Пятая страница.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 18–25.</span>', '4', 'rule', 'Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.'),
('Мединский курс (Том 2)', '3', 'الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا (отрицательный вопрос и «который из двух?»)', '<b>Суть правила.</b> بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَلَيْسَ هَذَا كِتَابَكَ؟ بَلَى.</b> — Разве это не твоя книга? Да, моя.</li><li><b dir="rtl" lang="ar">أَيُّهُمَا أَكْبَرُ؟</b> — Который из них двоих старше?</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 18–25.</span>', '5', 'rule', 'بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.'),
('Мединский курс (Том 2)', '4', 'إِسْنَادُ الْفِعْلِ الْمَاضِي (спряжение прошедшего времени)', '<b>Суть правила.</b> Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبْتُ.</b> — Я пошел.</li><li><b dir="rtl" lang="ar">ذَهَبُوا.</b> — Они пошли.</li><li><b dir="rtl" lang="ar">ذَهَبْنَ.</b> — Они, женщины, пошли.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 26–29.</span>', '1', 'rule', 'Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.'),
('Мединский курс (Том 2)', '4', 'مَا النَّافِيَةُ (отрицание прошедшего через مَا)', '<b>Суть правила.</b> مَا ставится перед прошедшим глаголом и не меняет его форму.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا ذَهَبَ حَامِدٌ.</b> — Хамид не пошел.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 26–29.</span>', '2', 'rule', 'مَا ставится перед прошедшим глаголом и не меняет его форму.'),
('Мединский курс (Том 2)', '4', 'لِأَنَّ (союз «потому что»)', '<b>Суть правила.</b> لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">غِبْتُ لِأَنَّنِي مَرِيضٌ.</b> — Я отсутствовал, потому что болен.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 26–29.</span>', '3', 'rule', 'لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.'),
('Мединский курс (Том 2)', '5', 'الْفَاعِلُ وَالْمَفْعُولُ بِهِ (исполнитель и прямое дополнение)', '<b>Суть правила.</b> Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ.</b> — Студент написал урок.</li><li><b dir="rtl" lang="ar">كَتَبَ الطُّلَّابُ الدَّرْسَ.</b> — Студенты написали урок.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 30–35.</span>', '1', 'rule', 'Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ (слитные местоимения-исполнители)', '<b>Суть правила.</b> تاء الفاعل, نا, ألف الاثنين, واو الجماعة и نون النسوة присоединяются к глаголу и сами обозначают исполнителя.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبْتُمْ.</b> — Вы написали.</li><li><b dir="rtl" lang="ar">كَتَبْنَ.</b> — Они, женщины, написали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 30–35.</span>', '2', 'rule', 'تاء الفاعل, نا, ألف الاثنين, واو الجماعة и نون النسوة присоединяются к глаголу и сами обозначают исполнителя.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ (слитные местоимения-дополнения)', '<b>Суть правила.</b> ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُهُ.</b> — Я увидел его.</li><li><b dir="rtl" lang="ar">سَأَلَنَا الْمُدَرِّسُ.</b> — Учитель спросил нас.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 30–35.</span>', '3', 'rule', 'ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.'),
('Мединский курс (Том 2)', '5', 'تَاءُ التَّأْنِيثِ السَّاكِنَةُ (показатель женского рода в прошедшем)', '<b>Суть правила.</b> С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبَتْ آمِنَةُ.</b> — Амина ушла.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 30–35.</span>', '4', 'rule', 'С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.'),
('Мединский курс (Том 2)', '6', 'تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ (согласование с женским исполнителем)', '<b>Суть правила.</b> Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تاء التأنيث.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَةُ.</b> — Студентка пришла.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '1', 'rule', 'Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تاء التأنيث.'),
('Мединский курс (Том 2)', '6', 'ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ (местоимения третьего лица как дополнение)', '<b>Суть правила.</b> ـهُ، ـهَا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُهُمْ.</b> — Я увидел их.</li><li><b dir="rtl" lang="ar">سَأَلْتُهَا.</b> — Я спросил ее.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '2', 'rule', 'ـهُ، ـهَا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.'),
('Мединский курс (Том 2)', '6', 'أَنَّ (союз «что»)', '<b>Суть правила.</b> أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَظُنُّ أَنَّ الْجَوَّ جَمِيلٌ.</b> — Я думаю, что погода хорошая.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '3', 'rule', 'أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.'),
('Мединский курс (Том 2)', '6', 'مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ (формы модели فَعْلَان)', '<b>Суть правила.</b> Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ عَطْشَانُ وَهِيَ عَطْشَى.</b> — Он и она испытывают жажду.</li><li><b dir="rtl" lang="ar">هُمْ عِطَاشٌ.</b> — Они испытывают жажду.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '4', 'rule', 'Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.'),
('Мединский курс (Том 2)', '6', 'أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ (три падежных состояния имен)', '<b>Суть правила.</b> Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبٌ، رَأَيْتُ طَالِبًا، مَرَرْتُ بِطَالِبٍ.</b> — Пришел студент; я увидел студента; я прошел мимо студента.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '5', 'rule', 'Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.'),
('Мединский курс (Том 2)', '6', 'لِمَ وَلِمَهْ وَهَاتِ («почему?» и «дай/принеси»)', '<b>Суть правила.</b> لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لِمَ غِبْتَ؟</b> — Почему ты отсутствовал?</li><li><b dir="rtl" lang="ar">هَاتِ الْكِتَابَ.</b> — Дай книгу.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 36–45.</span>', '6', 'rule', 'لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.'),
('Мединский курс (Том 2)', '7', 'تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ (женский исполнитель в единственном и множественном)', '<b>Суть правила.</b> С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتْ فَاطِمَةُ.</b> — Фатима пришла.</li><li><b dir="rtl" lang="ar">سَقَطَتِ الْكُتُبُ.</b> — Книги упали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 46–54.</span>', '1', 'rule', 'С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.'),
('Мединский курс (Том 2)', '7', 'الْتِقَاءُ السَّاكِنَيْنِ (встреча двух сукунов)', '<b>Суть правила.</b> Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَتِ الطَّالِبَةُ.</b> — Студентка сказала.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 46–54.</span>', '2', 'rule', 'Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.'),
('Мединский курс (Том 2)', '7', 'كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ (كَانَ со сказуемым-обстоятельством)', '<b>Суть правила.</b> كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَانَ فِي الْفَصْلِ طُلَّابٌ.</b> — В классе были студенты.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 46–54.</span>', '3', 'rule', 'كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.'),
('Мединский курс (Том 2)', '7', 'ذُو وَذَاتُ نَعْتًا (ذُو и ذَاتُ как определение)', '<b>Суть правила.</b> Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الرَّجُلُ ذُو اللِّحْيَةِ.</b> — Пришел мужчина с бородой.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 46–54.</span>', '4', 'rule', 'Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.'),
('Мединский курс (Том 2)', '8', 'جَدْوَلُ الْفِعْلِ الْمَاضِي (полная таблица прошедшего времени)', '<b>Суть правила.</b> Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا ذَهَبَا وَهُمَا ذَهَبَتَا.</b> — Они двое ушли: мужская и женская формы.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 55–58.</span>', '1', 'rule', 'Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.'),
('Мединский курс (Том 2)', '8', 'عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ (показатели формы и местоимения)', '<b>Суть правила.</b> Не каждое окончание является отдельным местоимением: تاء التأنيث лишь указывает женский род, а تاء الفاعل сама обозначает исполнителя.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَتْ فَاطِمَةُ؛ كَتَبْتُ.</b> — Фатима написала; я написал.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 55–58.</span>', '2', 'rule', 'Не каждое окончание является отдельным местоимением: تاء التأنيث лишь указывает женский род, а تاء الفاعل сама обозначает исполнителя.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ (скрытое и выраженное местоимение)', '<b>Суть правила.</b> Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ذَهَبَ: الْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</b> — В «ушел» скрытый исполнитель «он».</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 55–58.</span>', '3', 'rule', 'Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ (слитное и раздельное местоимение)', '<b>Суть правила.</b> Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ طَالِبٌ؛ كِتَابُهُ جَدِيدٌ.</b> — Он студент; его книга новая.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 55–58.</span>', '4', 'rule', 'Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.'),
('Мединский курс (Том 2)', '9', 'فِعْلُ التَّعَجُّبِ (форма восклицания مَا أَفْعَلَهُ)', '<b>Суть правила.</b> Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا أَجْمَلَ السَّمَاءَ!</b> — Как прекрасно небо!</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '1', 'rule', 'Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.'),
('Мединский курс (Том 2)', '9', 'الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ (обращение: одиночное и в идафе)', '<b>Суть правила.</b> Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَا مُحَمَّدُ!</b> — О Мухаммад!</li><li><b dir="rtl" lang="ar">يَا عَبْدَ اللهِ!</b> — О раб Аллаха!</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '2', 'rule', 'Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.'),
('Мединский курс (Том 2)', '9', 'جَمْعُ الْمُؤَنَّثِ السَّالِمُ (правильное женское множественное)', '<b>Суть правила.</b> В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَاتُ.</b> — Студентки пришли.</li><li><b dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَاتِ.</b> — Я увидел студенток.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '3', 'rule', 'В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.'),
('Мединский курс (Том 2)', '9', 'هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال (вопросительная أَ перед артиклем)', '<b>Суть правила.</b> При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">آلطَّالِبُ جَدِيدٌ؟</b> — Этот студент новый?</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '4', 'rule', 'При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.'),
('Мединский курс (Том 2)', '9', 'ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ (объектные местоимения и защитная ن)', '<b>Суть правила.</b> Перед ي говорящего у глагола появляется نون الوقاية: أَكْرَمَنِي. Она защищает основу от касры.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَأَلَنِي الْمُدَرِّسُ.</b> — Учитель спросил меня.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '5', 'rule', 'Перед ي говорящего у глагола появляется نون الوقاية: أَكْرَمَنِي. Она защищает основу от касры.'),
('Мединский курс (Том 2)', '9', 'حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ (удаление алифа в вопросительном مَا)', '<b>Суть правила.</b> После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">بِمَ كَتَبْتَ؟</b> — Чем ты написал?</li><li><b dir="rtl" lang="ar">عَمَّ تَسْأَلُ؟</b> — О чем ты спрашиваешь?</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '6', 'rule', 'После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.'),
('Мединский курс (Том 2)', '9', 'الْأَسْمَاءُ الْمَوْصُولَةُ (относительные местоимения)', '<b>Суть правила.</b> Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الطُّلَّابُ الَّذِينَ نَجَحُوا.</b> — Пришли студенты, которые сдали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 59–68.</span>', '7', 'rule', 'Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.'),
('Мединский курс (Том 2)', '10', 'الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ (прошедший и настоящее-будущее время)', '<b>Суть правила.</b> Прошедшее сообщает о завершенном действии. المضارع сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ.</b> — Он написал; он пишет.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 69–73.</span>', '1', 'rule', 'Прошедшее сообщает о завершенном действии. المضارع сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.'),
('Мединский курс (Том 2)', '10', 'إِعْرَابُ الْفِعْلِ الْمُضَارِعِ (изменение окончания المضارع)', '<b>Суть правила.</b> Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَكْتُبُ، لَنْ يَكْتُبَ، لَمْ يَكْتُبْ.</b> — Пишет; не будет писать; не писал.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 69–73.</span>', '2', 'rule', 'Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.'),
('Мединский курс (Том 2)', '10', 'الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩ (составные числа 21–99)', '<b>Суть правила.</b> Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَاحِدٌ وَعِشْرُونَ طَالِبًا.</b> — Двадцать один студент.</li><li><b dir="rtl" lang="ar">إِحْدَى وَعِشْرُونَ طَالِبَةً.</b> — Двадцать одна студентка.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 69–73.</span>', '3', 'rule', 'Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.'),
('Мединский курс (Том 2)', '10', 'أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ (огласовочные модели I породы)', '<b>Суть правила.</b> Гласная середины المضارع словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَتَبَ يَكْتُبُ؛ جَلَسَ يَجْلِسُ؛ فَتَحَ يَفْتَحُ.</b> — Писать; сидеть; открывать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 69–73.</span>', '4', 'rule', 'Гласная середины المضارع словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.'),
('Мединский курс (Том 2)', '11', 'إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ (спряжение المضارع)', '<b>Суть правила.</b> Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمْ يَكْتُبُونَ وَأَنْتِ تَكْتُبِينَ.</b> — Они пишут, и ты, женщина, пишешь.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '1', 'rule', 'Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.'),
('Мединский курс (Том 2)', '11', 'عَلَامَاتُ رَفْعِ الْمُضَارِعِ (признаки именительного состояния)', '<b>Суть правила.</b> Обычный المضارع имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ يَكْتُبُ؛ هُمْ يَكْتُبُونَ.</b> — Он пишет; они пишут.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '2', 'rule', 'Обычный المضارع имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.'),
('Мединский курс (Том 2)', '11', 'مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ (отрицание настоящего и будущее с سَـ)', '<b>Суть правила.</b> مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с المضارع и переносит действие в будущее.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا أَفْهَمُ هَذَا.</b> — Я не понимаю это.</li><li><b dir="rtl" lang="ar">سَأَذْهَبُ غَدًا.</b> — Я пойду завтра.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '3', 'rule', 'مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с المضارع и переносит действие в будущее.'),
('Мединский курс (Том 2)', '11', 'مَصْدَرُ فُعُولٍ (масдар модели فُعُول)', '<b>Суть правила.</b> Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">دَخَلَ دُخُولًا؛ خَرَجَ خُرُوجًا.</b> — Вошел — вход; вышел — выход.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '4', 'rule', 'Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.'),
('Мединский курс (Том 2)', '11', 'أَمَّا ... فَـ (оборот «что касается..., то...»)', '<b>Суть правила.</b> После أَمَّا называется тема, а ответ обычно начинается с فَـ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَمَّا خَالِدٌ فَهُوَ طَبِيبٌ.</b> — Что касается Халида, то он врач.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '5', 'rule', 'После أَمَّا называется тема, а ответ обычно начинается с فَـ.'),
('Мединский курс (Том 2)', '11', 'أَخِي وَأَخٌ لِي («мой брат» и «один из моих братьев»)', '<b>Суть правила.</b> أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا أَخِي؛ هَذَا أَخٌ لِي.</b> — Это мой брат; это один из моих братьев.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 74–83.</span>', '6', 'rule', 'أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.'),
('Мединский курс (Том 2)', '12', 'وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ (окончания المضارع)', '<b>Суть правила.</b> Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نون النسوة глагол неизменяем и перед ن стоит сукун.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ وَأَنْتِ تَكْتُبِينَ.</b> — Они, женщины, пишут, и ты пишешь.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 84–90.</span>', '1', 'rule', 'Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نون النسوة глагол неизменяем и перед ن стоит сукун.'),
('Мединский курс (Том 2)', '12', 'ظَرْفُ الزَّمَانِ (обстоятельство времени)', '<b>Суть правила.</b> Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَأَزُورُكَ مَسَاءً.</b> — Я навещу тебя вечером.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 84–90.</span>', '2', 'rule', 'Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.'),
('Мединский курс (Том 2)', '12', 'إِنَّ بَعْدَ الْقَوْلِ (إِنَّ после глагола речи)', '<b>Суть правила.</b> После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ: إِنَّ الِامْتِحَانَ غَدًا.</b> — Учитель сказал: «Экзамен завтра».</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 84–90.</span>', '3', 'rule', 'После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.'),
('Мединский курс (Том 2)', '13', 'إِنَّ وَأَنَّ (различие إِنَّ и أَنَّ)', '<b>Суть правила.</b> إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">عَلِمْتُ أَنَّ الدَّرْسَ سَهْلٌ.</b> — Я узнал, что урок легкий.</li><li><b dir="rtl" lang="ar">قَالَ: إِنَّ الدَّرْسَ سَهْلٌ.</b> — Он сказал: «Урок легкий».</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 91–94.</span>', '1', 'rule', 'إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.'),
('Мединский курс (Том 2)', '13', 'مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ (повторение спряжения المضارع)', '<b>Суть правила.</b> Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَنَا أَدْرُسُ، نَحْنُ نَدْرُسُ، هُمْ يَدْرُسُونَ.</b> — Я учусь, мы учимся, они учатся.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 91–94.</span>', '2', 'rule', 'Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.'),
('Мединский курс (Том 2)', '14', 'فِعْلُ الْأَمْرِ (повелительное наклонение)', '<b>Суть правила.</b> Повелительная форма строится для второго лица от усеченной формы المضارع: убирается تَـ, а при невозможности начать с сукуна добавляется همزة الوصل.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">تَكْتُبُ ← لَمْ تَكْتُبْ ← اُكْتُبْ.</b> — Ты пишешь → ты не писал → пиши.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 95–102.</span>', '1', 'rule', 'Повелительная форма строится для второго лица от усеченной формы المضارع: убирается تَـ, а при невозможности начать с сукуна добавляется همزة الوصل.'),
('Мединский курс (Том 2)', '14', 'هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ (соединительная хамза)', '<b>Суть правила.</b> Огласовка начальной хамзы зависит от гласной середины المضارع: при дамме обычно اُ, иначе اِ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَكْتُبُ: اُكْتُبْ؛ يَجْلِسُ: اِجْلِسْ.</b> — Пиши; сядь.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 95–102.</span>', '2', 'rule', 'Огласовка начальной хамзы зависит от гласной середины المضارع: при дамме обычно اُ, иначе اِ.'),
('Мединский курс (Том 2)', '14', 'تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ (пять форм повелительного)', '<b>Суть правила.</b> Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">اُدْخُلُوا الْفَصْلَ.</b> — Войдите в класс.</li><li><b dir="rtl" lang="ar">اُكْتُبْنَ الدَّرْسَ.</b> — Пишите урок, женщины.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 95–102.</span>', '3', 'rule', 'Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.'),
('Мединский курс (Том 2)', '15', 'لَا النَّاهِيَةُ (запретительная لَا)', '<b>Суть правила.</b> لَا النَّاهِيَةُ означает «не делай» и переводит المضارع в усеченное состояние.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا تَذْهَبْ.</b> — Не уходи.</li><li><b dir="rtl" lang="ar">لَا تَكْتُبُوا.</b> — Не пишите.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 103–108.</span>', '1', 'rule', 'لَا النَّاهِيَةُ означает «не делай» и переводит المضارع в усеченное состояние.'),
('Мединский курс (Том 2)', '15', 'لَا النَّافِيَةُ وَلَا النَّاهِيَةُ (отрицательная и запретительная لَا)', '<b>Суть правила.</b> Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا يَذْهَبُ حَامِدٌ؛ لَا تَذْهَبْ يَا حَامِدُ.</b> — Хамид не идет; не уходи, Хамид.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 103–108.</span>', '2', 'rule', 'Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.'),
('Мединский курс (Том 2)', '15', 'كَادَ («едва не, почти»)', '<b>Суть правила.</b> كَادَ — ناقصный глагол. Его имя именительное, а сказуемое обычно выражено المضارع без أَنْ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</b> — Ребенок едва не упал.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 103–108.</span>', '3', 'rule', 'كَادَ — ناقصный глагол. Его имя именительное, а сказуемое обычно выражено المضارع без أَنْ.'),
('Мединский курс (Том 2)', '15', 'مُرَاجَعَةُ التَّعَجُّبِ (повторение восклицательной модели)', '<b>Суть правила.</b> В модели مَا أَفْعَلَ объект впечатления стоит в винительном.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا أَحْسَنَ هَذَا الْكِتَابَ!</b> — Как хороша эта книга!</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 103–108.</span>', '4', 'rule', 'В модели مَا أَفْعَلَ объект впечатления стоит в винительном.'),
('Мединский курс (Том 2)', '16', 'إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ (спряжение «хотеть» и أَنْ + глагол)', '<b>Суть правила.</b> У أَرَادَ المضارع имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + المضارع является смысловым эквивалентом масдара.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ = أُرِيدُ التَّعَلُّمَ.</b> — Я хочу учиться = я хочу обучения.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '1', 'rule', 'У أَرَادَ المضارع имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + المضارع является смысловым эквивалентом масдара.'),
('Мединский курс (Том 2)', '16', 'مَا الْمَوْصُولَةُ (относительное مَا «то, что»)', '<b>Суть правила.</b> مَا может означать «то, что» и связывать главное предложение с поясняющим.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَفْهَمُ مَا تَقُولُ.</b> — Я понимаю то, что ты говоришь.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '2', 'rule', 'مَا может означать «то, что» и связывать главное предложение с поясняющим.'),
('Мединский курс (Том 2)', '16', 'أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ (цвета мужского и женского рода)', '<b>Суть правила.</b> Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно ممنوع من الصرف.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَمِيصٌ أَبْيَضُ وَسَيَّارَةٌ بَيْضَاءُ.</b> — Белая рубашка и белый автомобиль.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '3', 'rule', 'Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно ممنوع من الصرف.'),
('Мединский курс (Том 2)', '16', 'الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو (особые собственные имена)', '<b>Суть правила.</b> Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">سَلَّمْتُ عَلَى عُمَرَ؛ جَاءَ عَمْرٌو.</b> — Я поприветствовал Умара; Амр пришел.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '4', 'rule', 'Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.'),
('Мединский курс (Том 2)', '16', 'آخَرُ وَأُخْرَى وَغَيْرُ («другой» и «иной, кроме»)', '<b>Суть правила.</b> آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ كِتَابًا آخَرَ.</b> — Я хочу другую книгу.</li><li><b dir="rtl" lang="ar">جَاءَ غَيْرُ خَالِدٍ.</b> — Пришел не Халид.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '5', 'rule', 'آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.'),
('Мединский курс (Том 2)', '16', 'إِعْرَابُ ذُو (склонение ذُو)', '<b>Суть правила.</b> Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُ رَجُلًا ذَا عِلْمٍ.</b> — Я увидел знающего человека.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 109–118.</span>', '6', 'rule', 'Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.'),
('Мединский курс (Том 2)', '17', 'نَوَاصِبُ الْمُضَارِعِ (частицы винительного состояния)', '<b>Суть правила.</b> أَنْ، لَنْ и لام التعليل ставят المضارع в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَنْ أَذْهَبَ؛ لَنْ أَتَأَخَّرَ.</b> — Я хочу пойти; я не опоздаю.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 119–126.</span>', '1', 'rule', 'أَنْ، لَنْ и لام التعليل ставят المضارع в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.'),
('Мединский курс (Том 2)', '17', 'أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ («чтобы», «не будет» и لام цели)', '<b>Суть правила.</b> أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях المضارع منصوب.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جِئْتُ لِأَتَعَلَّمَ.</b> — Я пришел, чтобы учиться.</li><li><b dir="rtl" lang="ar">لَنْ نَغِيبَ غَدًا.</b> — Мы не будем отсутствовать завтра.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 119–126.</span>', '2', 'rule', 'أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях المضارع منصوب.'),
('Мединский курс (Том 2)', '17', 'عَلَامَاتُ نَصْبِ الْمُضَارِعِ (признаки винительного состояния)', '<b>Суть правила.</b> Признак — явная или предполагаемая фатха; у الأفعال الخمسة — удаление ن.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَنْ يَكْتُبُوا.</b> — Они не будут писать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 119–126.</span>', '3', 'rule', 'Признак — явная или предполагаемая фатха; у الأفعال الخمسة — удаление ن.'),
('Мединский курс (Том 2)', '17', 'يُمْكِنُ وَمُنْذُ («возможно» и «с тех пор»)', '<b>Суть правила.</b> يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يُمْكِنُ أَنْ نَبْدَأَ؛ مَا رَأَيْتُهُ مُنْذُ أُسْبُوعٍ.</b> — Мы можем начать; я не видел его неделю.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 119–126.</span>', '4', 'rule', 'يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.'),
('Мединский курс (Том 2)', '17', 'رَأَى يَرَى (особое спряжение «видеть»)', '<b>Суть правила.</b> В المضارع хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَرَى الْقَمَرَ.</b> — Я вижу луну.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 119–126.</span>', '5', 'rule', 'В المضارع хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.'),
('Мединский курс (Том 2)', '18', 'حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ (удаление ن у пяти форм)', '<b>Суть правила.</b> После винительных и усечных частиц формы ـانِ، ـونَ، ـينَ теряют ن.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَنْ تَكْتُبُوا؛ لَمْ تَكْتُبُوا.</b> — Вы не будете писать; вы не писали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 127–132.</span>', '1', 'rule', 'После винительных и усечных частиц формы ـانِ، ـونَ، ـينَ теряют ن.'),
('Мединский курс (Том 2)', '18', 'نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ (женская ن в المضارع)', '<b>Суть правила.</b> Форма с نون النسوة строится на сукуне и не меняется после частиц винительного или усеченного состояния.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ؛ لَنْ يَكْتُبْنَ.</b> — Они пишут; они не будут писать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 127–132.</span>', '2', 'rule', 'Форма с نون النسوة строится на сукуне и не меняется после частиц винительного или усеченного состояния.'),
('Мединский курс (Том 2)', '18', 'أَلَّا (слитное أَنْ لَا)', '<b>Суть правила.</b> أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أُرِيدُ أَلَّا تَتَأَخَّرَ.</b> — Я хочу, чтобы ты не опаздывал.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 127–132.</span>', '3', 'rule', 'أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.'),
('Мединский курс (Том 2)', '18', 'كَافُ التَّشْبِيهِ (предлог сравнения كَـ)', '<b>Суть правила.</b> كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ كَالْأَسَدِ.</b> — Он как лев.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 127–132.</span>', '4', 'rule', 'كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.'),
('Мединский курс (Том 2)', '18', 'الْأَفْعَالُ الْخَمْسَةُ (пять глагольных форм)', '<b>Суть правила.</b> Это المضارع с ألف الاثنين, واو الجماعة или ياء المخاطبة. Они именительны с сохранением ن и винительны/усечены с ее удалением.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ، هُمْ يَكْتُبُونَ، أَنْتِ تَكْتُبِينَ.</b> — Они двое пишут, они пишут, ты пишешь.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 127–132.</span>', '5', 'rule', 'Это المضارع с ألف الاثنين, واو الجماعة или ياء المخاطبة. Они именительны с сохранением ن и винительны/усечены с ее удалением.'),
('Мединский курс (Том 2)', '19', 'نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ (отрицание трех времен)', '<b>Суть правила.</b> Прошедшее отрицают مَا или لَمْ + المضارع, настоящее — لَا/مَا + المضارع, будущее — لَنْ + المضارع.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا ذَهَبَ؛ لَا يَذْهَبُ؛ لَنْ يَذْهَبَ.</b> — Не пошел; не идет; не пойдет.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 133–137.</span>', '1', 'rule', 'Прошедшее отрицают مَا или لَمْ + المضارع, настоящее — لَا/مَا + المضارع, будущее — لَنْ + المضارع.'),
('Мединский курс (Том 2)', '19', 'قَطُّ وَأَبَدًا («никогда» в прошлом и будущем)', '<b>Суть правила.</b> قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَا رَأَيْتُهُ قَطُّ؛ لَنْ أَنْسَاهُ أَبَدًا.</b> — Я никогда его не видел; я никогда его не забуду.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 133–137.</span>', '2', 'rule', 'قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.'),
('Мединский курс (Том 2)', '20', 'الْمُثَنَّى وَإِعْرَابُهُ (двойственное число и его падежи)', '<b>Суть правила.</b> Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبَانِ؛ رَأَيْتُ طَالِبَيْنِ.</b> — Пришли два студента; я увидел двух студентов.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 138–143.</span>', '1', 'rule', 'Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '20', 'أَحَدُهُمَا وَالْآخَرُ («один из них и другой»)', '<b>Суть правила.</b> أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَحَدُهُمَا طَبِيبٌ وَالْآخَرُ مُهَنْدِسٌ.</b> — Один из них врач, другой инженер.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 138–143.</span>', '2', 'rule', 'أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.'),
('Мединский курс (Том 2)', '20', 'إِعْرَابُ ذُو وَذَاتُ (склонение ذُو и ذَاتُ)', '<b>Суть правила.</b> ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">مَرَرْتُ بِرَجُلٍ ذِي عِلْمٍ.</b> — Я прошел мимо знающего человека.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 138–143.</span>', '3', 'rule', 'ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.'),
('Мединский курс (Том 2)', '21', 'لَمْ وَلَمَّا (отрицательные усеченные частицы)', '<b>Суть правила.</b> Обе частицы усекают المضارع и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ يَصِلْ؛ لَمَّا يَصِلْ.</b> — Он не прибыл; он еще не прибыл.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 144–152.</span>', '1', 'rule', 'Обе частицы усекают المضارع и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.'),
('Мединский курс (Том 2)', '21', 'عَلَامَاتُ جَزْمِ الْمُضَارِعِ (признаки усеченного состояния)', '<b>Суть правила.</b> Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ يَكْتُبْ؛ لَمْ يَمْشِ؛ لَمْ يَكْتُبُوا.</b> — Не писал; не шел; они не писали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 144–152.</span>', '2', 'rule', 'Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.'),
('Мединский курс (Том 2)', '21', 'أَقْسَامُ الْكَلِمَةِ (три части речи)', '<b>Суть правила.</b> Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كِتَابٌ اسم، كَتَبَ فعل، فِي حرف.</b> — «Книга» — имя, «написал» — глагол, «в» — частица.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 144–152.</span>', '3', 'rule', 'Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.'),
('Мединский курс (Том 2)', '21', 'الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ (именное и глагольное предложение)', '<b>Суть правила.</b> Именное начинается именем и обычно содержит مبتدأ/خبر. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ؛ كَتَبَ الطَّالِبُ الدَّرْسَ.</b> — Студент усердный; студент написал урок.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 144–152.</span>', '4', 'rule', 'Именное начинается именем и обычно содержит مبتدأ/خبر. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.'),
('Мединский курс (Том 2)', '21', 'اللَّاتِي وَاللَّائِي (женское множественное относительное местоимение)', '<b>Суть правила.</b> Обе формы употребляются для группы женского рода и вводят поясняющее предложение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ اللَّاتِي نَجَحْنَ.</b> — Пришли студентки, которые сдали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 144–152.</span>', '5', 'rule', 'Обе формы употребляются для группы женского рода и вводят поясняющее предложение.'),
('Мединский курс (Том 2)', '22', 'حَالَاتُ الْمُضَارِعِ الثَّلَاثُ (три состояния المضارع)', '<b>Суть правила.</b> Без управляющей частицы глагол مرفوع: يَكْتُبُ. После أَنْ/لَنْ/لِـ он منصوب: يَكْتُبَ. После لَمْ/لَمَّا/لَا الناهية он مجزوم: يَكْتُبْ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُوَ يَدْرُسُ؛ لَنْ يَدْرُسَ؛ لَمْ يَدْرُسْ.</b> — Он учится; не будет учиться; не учился.</li></ul><br><br><div class="rule-note"><b>Как проверить себя.</b> Сначала найдите частицу перед глаголом, затем определите состояние и только после этого выбирайте окончание.</div><br><br><span class="rule-source-note">Книга, том 2: страницы 153–153.</span>', '1', 'rule', 'Без управляющей частицы глагол مرفوع: يَكْتُبُ. После أَنْ/لَنْ/لِـ он منصوب: يَكْتُبَ. После لَمْ/لَمَّا/لَا الناهية он مجزوم: يَكْتُبْ.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ (падежи правильного мужского множественного)', '<b>Суть правила.</b> Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُونَ؛ رَأَيْتُ الْمُدَرِّسِينَ.</b> — Пришли учителя; я увидел учителей.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 154–160.</span>', '1', 'rule', 'Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ أَلْفَاظِ الْعُقُودِ (склонение десятков)', '<b>Суть правила.</b> عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">فِي الْفَصْلِ ثَلَاثُونَ طَالِبًا؛ رَأَيْتُ ثَلَاثِينَ.</b> — В классе тридцать студентов; я увидел тридцать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 154–160.</span>', '2', 'rule', 'عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.'),
('Мединский курс (Том 2)', '23', 'نَفْيُ الْمَاضِي بِـلَا (отрицание повторяющегося прошлого через لَا)', '<b>Суть правила.</b> لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَا أَكَلَ وَلَا شَرِبَ.</b> — Он не ел и не пил.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 154–160.</span>', '3', 'rule', 'لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.'),
('Мединский курс (Том 2)', '24', 'الْعَدَدَانِ ١ وَ٢ (числа один и два)', '<b>Суть правила.</b> Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">طَالِبٌ وَاحِدٌ؛ طَالِبَتَانِ اثْنَتَانِ.</b> — Один студент; две студентки.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 161–166.</span>', '1', 'rule', 'Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ٣–١٠ (числа 3–10)', '<b>Суть правила.</b> Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةُ كُتُبٍ؛ ثَلَاثُ سَيَّارَاتٍ.</b> — Три книги; три автомобиля.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 161–166.</span>', '2', 'rule', 'Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ١١–١٩ (числа 11–19)', '<b>Суть правила.</b> В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَحَدَ عَشَرَ طَالِبًا؛ خَمْسَ عَشْرَةَ امْرَأَةً.</b> — Одиннадцать студентов; пятнадцать женщин.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 161–166.</span>', '3', 'rule', 'В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.'),
('Мединский курс (Том 2)', '24', 'أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ (десятки и составные числа)', '<b>Суть правила.</b> Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثَةٌ وَعِشْرُونَ كِتَابًا.</b> — Двадцать три книги.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 161–166.</span>', '4', 'rule', 'Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.'),
('Мединский курс (Том 2)', '24', 'الْمِئَاتُ وَالْآلَافُ (сотни и тысячи)', '<b>Суть правила.</b> После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ثَلَاثُمِائَةِ كِتَابٍ؛ خَمْسَةُ آلَافِ طَالِبٍ.</b> — Триста книг; пять тысяч студентов.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 161–166.</span>', '5', 'rule', 'После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.'),
('Мединский курс (Том 2)', '25', 'كَانَ وَمَا زَالَ («был» и «все еще»)', '<b>Суть правила.</b> Оба ناقصных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كَانَ الْبَابُ مَفْتُوحًا؛ مَا زَالَ الطَّالِبُ مَرِيضًا.</b> — Дверь была открыта; студент все еще болен.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 167–172.</span>', '1', 'rule', 'Оба ناقصных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.'),
('Мединский курс (Том 2)', '25', 'الْأَسْمَاءُ الْخَمْسَةُ (пять особых имен)', '<b>Суть правила.</b> أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ أَبُوكَ؛ رَأَيْتُ أَبَاكَ؛ سَلَّمْتُ عَلَى أَبِيكَ.</b> — Твой отец пришел; я увидел и поприветствовал твоего отца.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 167–172.</span>', '2', 'rule', 'أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.'),
('Мединский курс (Том 2)', '25', 'شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ (условия склонения пяти имен)', '<b>Суть правила.</b> Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذَا أَخُو مُحَمَّدٍ.</b> — Это брат Мухаммада.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 167–172.</span>', '3', 'rule', 'Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.'),
('Мединский курс (Том 2)', '26', 'الْفِعْلُ الْمِثَالُ الْوَاوِيُّ (слабый глагол с و в начале)', '<b>Суть правила.</b> В المضارع ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَصَلَ الْقِطَارُ؛ يَصِلُ غَدًا؛ عِدْ.</b> — Поезд прибыл; прибудет завтра; обещай.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 173–179.</span>', '1', 'rule', 'В المضارع ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.'),
('Мединский курс (Том 2)', '26', 'التَّصْغِيرُ (уменьшительная форма)', '<b>Суть правила.</b> Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">كِتَابٌ → كُتَيِّبٌ.</b> — Книга → книжечка.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 173–179.</span>', '2', 'rule', 'Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.'),
('Мединский курс (Том 2)', '26', 'اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ (сравнительная степень удвоенного глагола)', '<b>Суть правила.</b> При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">شَدَّ → أَشَدُّ.</b> — Быть сильным → сильнее.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 173–179.</span>', '3', 'rule', 'При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.'),
('Мединский курс (Том 2)', '26', 'هَا هُوَ ذَا (оборот «вот он»)', '<b>Суть правила.</b> هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَا هُوَ ذَا؛ هَا هِيَ ذِهِ.</b> — Вот он; вот она.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 173–179.</span>', '4', 'rule', 'هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.'),
('Мединский курс (Том 2)', '26', 'يَجِبُ وَمَصْدَرُ ذَهَبَ («необходимо» и масдар ذَهَبَ)', '<b>Суть правила.</b> После يَجِبُ часто употребляется أَنْ + المضارع. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَجِبُ أَنْ تَذْهَبَ؛ أُرِيدُ الذَّهَابَ.</b> — Тебе нужно пойти; я хочу пойти.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 173–179.</span>', '5', 'rule', 'После يَجِبُ часто употребляется أَنْ + المضارع. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.'),
('Мединский курс (Том 2)', '27', 'الْفِعْلُ الْأَجْوَفُ (пустой глагол со слабой средней буквой)', '<b>Суть правила.</b> У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالَ يَقُولُ؛ بَاعَ يَبِيعُ.</b> — Сказать; продавать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 180–192.</span>', '1', 'rule', 'У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.'),
('Мединский курс (Том 2)', '27', 'إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي (прошедшее пустого глагола)', '<b>Суть правила.</b> Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">قَالُوا وَقُلْنَا.</b> — Они сказали, и мы сказали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 180–192.</span>', '2', 'rule', 'Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.'),
('Мединский курс (Том 2)', '27', 'الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ (пустой глагол в المضارع и повелительном)', '<b>Суть правила.</b> В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَقُولُ، لَنْ يَقُولَ، لَمْ يَقُلْ، قُلْ.</b> — Говорит; не будет говорить; не говорил; скажи.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 180–192.</span>', '3', 'rule', 'В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.'),
('Мединский курс (Том 2)', '27', 'أَصْلُ الْحَرْفِ الْمُعْتَلِّ (как определить و или ي в корне)', '<b>Суть правила.</b> Смотрите на المضارع или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">صَامَ يَصُومُ: الجذر ص و م.</b> — Поститься: корень ص و م.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 180–192.</span>', '4', 'rule', 'Смотрите на المضارع или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.'),
('Мединский курс (Том 2)', '27', 'الْقَسَمُ وَلَقَدْ وَظَنَّ (клятва, усиление и два дополнения)', '<b>Суть правила.</b> После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَاللهِ لَقَدْ صَدَقَ؛ ظَنَنْتُ خَالِدًا طَبِيبًا.</b> — Клянусь Аллахом, он сказал правду; я считал Халида врачом.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 180–192.</span>', '5', 'rule', 'После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.'),
('Мединский курс (Том 2)', '28', 'الْفِعْلُ النَّاقِصُ (слабый глагол с последней و/ي)', '<b>Суть правила.</b> Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется المضارع и масдаром.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَدَى يَهْدِي؛ دَعَا يَدْعُو.</b> — Вести прямым путем; звать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 193–204.</span>', '1', 'rule', 'Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется المضارع и масдаром.'),
('Мединский курс (Том 2)', '28', 'إِسْنَادُ النَّاقِصِ فِي الْمَاضِي (прошедшее слабого конечного глагола)', '<b>Суть правила.</b> Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَمَيْتُ الْكُرَةَ.</b> — Я бросил мяч.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 193–204.</span>', '2', 'rule', 'Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.'),
('Мединский курс (Том 2)', '28', 'النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ (конечнослабый глагол в المضارع и повелительном)', '<b>Суть правила.</b> В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَمْشِي، لَنْ يَمْشِيَ، لَمْ يَمْشِ، اِمْشِ.</b> — Идет; не пойдет; не шел; иди.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 193–204.</span>', '3', 'rule', 'В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.'),
('Мединский курс (Том 2)', '28', 'رَأَى وَأَرِنِي («увидел» и «покажи мне»)', '<b>Суть правила.</b> رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">أَرِنِي كِتَابَكَ.</b> — Покажи мне свою книгу.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 193–204.</span>', '4', 'rule', 'رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.'),
('Мединский курс (Том 2)', '29', 'الْفِعْلُ الْمُضَعَّفُ (удвоенный глагол)', '<b>Суть правила.</b> Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَدَّ الطَّالِبُ الْكِتَابَ.</b> — Студент вернул книгу.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 205–212.</span>', '1', 'rule', 'Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.'),
('Мединский курс (Том 2)', '29', 'إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي (прошедшее удвоенного глагола)', '<b>Суть правила.</b> Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">ظَنَنْتُ؛ ظَنُّوا.</b> — Я подумал; они подумали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 205–212.</span>', '2', 'rule', 'Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.'),
('Мединский курс (Том 2)', '29', 'الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ (удвоенный глагол в المضارع и повелительном)', '<b>Суть правила.</b> В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">يَرُدُّ، لَنْ يَرُدَّ، لَمْ يَرُدَّ/يَرْدُدْ، رُدَّ.</b> — Возвращает; не будет; не вернул; верни.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 205–212.</span>', '3', 'rule', 'В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.'),
('Мединский курс (Том 2)', '29', 'قَطُّ وَأَبَدًا (наречия усиления отрицания)', '<b>Суть правила.</b> قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">لَمْ أَكْذِبْ قَطُّ؛ لَنْ أَكْذِبَ أَبَدًا.</b> — Я никогда не лгал; я никогда не буду лгать.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 205–212.</span>', '4', 'rule', 'قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.'),
('Мединский курс (Том 2)', '29', 'مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ (сводка слабых глаголов)', '<b>Суть правила.</b> مثال имеет слабую первую, أجوف — среднюю, ناقص — последнюю коренную. Место слабой буквы определяет изменения.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">وَعَدَ مثال، قَالَ أجوف، دَعَا ناقص.</b> — Обещать — начально-слабый; говорить — пустой; звать — конечнослабый.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 205–212.</span>', '5', 'rule', 'مثال имеет слабую первую, أجوف — среднюю, ناقص — последнюю коренную. Место слабой буквы определяет изменения.'),
('Мединский курс (Том 2)', '30', 'أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ (двойственное число глагола)', '<b>Суть правила.</b> Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">الطَّالِبَانِ ذَهَبَا وَالطَّالِبَتَانِ ذَهَبَتَا.</b> — Два студента ушли, и две студентки ушли.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 213–217.</span>', '1', 'rule', 'Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.'),
('Мединский курс (Том 2)', '30', 'الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ (двойственные формы среди пяти глаголов)', '<b>Суть правила.</b> يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هُمَا يَكْتُبَانِ؛ لَنْ يَكْتُبَا؛ لَمْ يَكْتُبَا.</b> — Они двое пишут; не будут писать; не писали.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 213–217.</span>', '2', 'rule', 'يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.'),
('Мединский курс (Том 2)', '31', 'النَّعْتُ وَالْمَنْعُوتُ (прилагательное и определяемое имя)', '<b>Суть правила.</b> Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">جَاءَ طَالِبٌ جَدِيدٌ.</b> — Пришел новый студент.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 218–220.</span>', '1', 'rule', 'Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.'),
('Мединский курс (Том 2)', '31', 'مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ (согласование определения)', '<b>Суть правила.</b> Определение согласуется в четырех признаках: падеже, определенности, роде и числе.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَةَ الْجَدِيدَةَ.</b> — Я увидел новую студентку.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 218–220.</span>', '2', 'rule', 'Определение согласуется в четырех признаках: падеже, определенности, роде и числе.'),
('Мединский курс (Том 2)', '31', 'نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ (определение неодушевленного множественного)', '<b>Суть правила.</b> Неодушевленное множественное обычно получает определение женского единственного рода.<br><br><b>Примеры.</b><ul><li><b dir="rtl" lang="ar">هَذِهِ كُتُبٌ جَدِيدَةٌ.</b> — Это новые книги.</li></ul><br><br><span class="rule-source-note">Книга, том 2: страницы 218–220.</span>', '3', 'rule', 'Неодушевленное множественное обычно получает определение женского единственного рода.');
